// ── Node: Validate Email ────────────────────────────────────────────────────
// Enforces business rules BEFORE any storage or DB operations.
// Returns the email if valid, stops the workflow with a logged error if not.

const email = $input.first().json;

// Rule 1: Must have message ID (deduplication key)
if (!email.id) {
  throw new Error('VALIDATION_FAILED: Missing Outlook message ID — cannot deduplicate.');
}

// Rule 2: Must have a subject
if (!email.subject || email.subject.trim() === '') {
  throw new Error('VALIDATION_FAILED: Email has no subject — rejecting.');
}

// Rule 3: Must have a sender
if (!email.from?.emailAddress?.address) {
  throw new Error('VALIDATION_FAILED: Email has no sender — rejecting.');
}

// Rule 4: Must have at least one PDF attachment
const attachments = email.attachments || [];
const pdfAttachments = attachments.filter(a => {
  const name = (a.name || '').toLowerCase();
  const mime = (a.contentType || '').toLowerCase();
  return name.endsWith('.pdf') || mime.includes('pdf');
});

if (pdfAttachments.length === 0) {
  throw new Error('VALIDATION_FAILED: No PDF attachments found — rejecting email.');
}

// Rule 5: Reject non-PDF MIME types we cannot process
const ALLOWED_MIMES = ['application/pdf', 'image/jpeg', 'image/png', 'image/tiff'];
const allAttachments = attachments.filter(a => {
  const mime = (a.contentType || '').toLowerCase();
  return ALLOWED_MIMES.some(allowed => mime.includes(allowed.split('/')[1]));
});

return [{
  json: {
    ...email,
    _validated: true,
    _pdfAttachments: pdfAttachments,
    _allValidAttachments: allAttachments.length > 0 ? allAttachments : pdfAttachments,
  }
}];

// ── Node: Prepare Attachment Loop ───────────────────────────────────────────
// Splits the attachments array into individual items for the upload loop.
// Each item contains the attachment data PLUS the parent email context.

const email = $input.first().json;
const attachments = email._allValidAttachments || [];

return attachments.map((attachment, index) => ({
  json: {
    attachment,
    attachmentIndex: index,
    totalAttachments: attachments.length,
    // Parent email context carried through the loop
    emailContext: {
      outlookMessageId: email.id,
      internetMessageId: email.internetMessageId,
      conversationId: email.conversationId,
      subject: email.subject,
      body: email.body?.content || email.bodyPreview || '',
      bodyPreview: email.bodyPreview || '',
      senderEmail: email.from?.emailAddress?.address || '',
      senderName: email.from?.emailAddress?.name || '',
      recipients: (email.toRecipients || []).map(r => ({
        email: r.emailAddress?.address || '',
        name: r.emailAddress?.name || '',
      })),
      receivedAt: email.receivedDateTime || new Date().toISOString(),
    }
  }
}));

// ── Node: Enrich with Storage Path ──────────────────────────────────────────
// Adds the confirmed storage path to each attachment record.
// Calculates a simple file size from available data.

const item = $input.first().json;
const uploadResponse = $input.first().json;

// Build the storage path consistent with the upload URL
const storagePath = `${item.emailContext.outlookMessageId}/${item.attachment.name}`;

return [{
  json: {
    ...item,
    uploadedAttachment: {
      original_filename: item.attachment.name,
      mime_type: item.attachment.contentType || 'application/octet-stream',
      file_size_bytes: item.attachment.size || 0,
      storage_path: storagePath,
      storage_provider: 'supabase',
      checksum: null,
    }
  }
}];

// ── Node: Build FastAPI Webhook Payload ─────────────────────────────────────
// Assembles the final JSON payload to send to FastAPI.
// This is the exact contract defined by OutlookWebhookPayload schema.

const items = $input.all();
const first = items[0].json;
const emailCtx = first.emailContext || first.uploadedAttachments?.[0]?.emailContext;
const attachments = items.map(i => i.json.uploadedAttachment).filter(Boolean);

const payload = {
  outlook_message_id: emailCtx.outlookMessageId,
  internet_message_id: emailCtx.internetMessageId || null,
  conversation_id: emailCtx.conversationId || null,
  subject: emailCtx.subject,
  body: emailCtx.body,
  body_preview: emailCtx.bodyPreview || null,
  sender_email: emailCtx.senderEmail,
  sender_name: emailCtx.senderName || null,
  recipients: emailCtx.recipients || [],
  received_at: emailCtx.receivedAt,
  attachments: attachments,
};

return [{ json: payload }];

// ── Node: Log Success ────────────────────────────────────────────────────────
const response = $input.first().json;
console.log('✅ Project created successfully:', {
  project_id: response.project_id,
  project_number: response.project_number,
  email_id: response.email_id,
  files_ingested: response.files_ingested,
  drawings_created: response.drawings_created,
});
return [{ json: { success: true, ...response } }];

// ── Node: Handle Error ───────────────────────────────────────────────────────
// Catches errors from any upstream node and logs them.
// In production, this should also write to an error_logs table.

const error = $input.first();
console.error('❌ Email intake failed:', {
  error: error.json?.error || error.json?.detail || 'Unknown error',
  timestamp: new Date().toISOString(),
});
return [{ json: { success: false, error: error.json } }];
